/* eslint-disable @typescript-eslint/no-unused-vars */
import { useEffect, useRef, useState } from 'react'
import { Activity, ArrowLeft, BarChart3, CalendarDays, Camera, Check, ChevronDown, CircleHelp, Clock3, Dumbbell, Download, Flame, History, Moon, Pause, Play, Plus, RotateCcw, Settings, Square, Sun, Trash2, Trophy, Upload, Video, X, Zap } from 'lucide-react'
import type { AppSettings, AppState, BodyWeightEntry, ExerciseSet, Page, RoutineExercise, TechniqueAnalysis, WorkoutRoutine, WorkoutSession } from './types'
import { loadState, saveState } from './db'
import { defaultState } from './seed'
import { detectNewRecords, sessionVolume } from './analytics'
import { analyzers, type ExerciseAnalyzer, type Landmark, type PoseFrame, type TechniqueFeedback } from './technique'
import { parseWorkoutWorkbook } from './importExcel'
import { formatDate, formatDuration, formatNumber, formatTimerShort, isoDate, isSameWeek, uid } from './utils'

function App() {
  const [state, setState] = useState<AppState>(() => defaultState())
  const [ready, setReady] = useState(false)
  const [page, setPage] = useState<Page>('dashboard')
  const [selectedSession, setSelectedSession] = useState<string>()
  const [toast, setToast] = useState<string>()

  useEffect(() => { loadState(defaultState()).then((loaded) => { setState(loaded); setReady(true) }) }, [])
  useEffect(() => { if (ready) void saveState(state) }, [state, ready])
  useEffect(() => { document.documentElement.dataset.theme = state.settings.theme === 'system' ? 'dark' : state.settings.theme; if ('serviceWorker' in navigator) void navigator.serviceWorker.register('/sw.js').catch(() => undefined) }, [state.settings.theme])
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(undefined), 3200); return () => window.clearTimeout(timer) }, [toast])

  const activeSession = state.activeSession ? state.sessions.find((session) => session.id === state.activeSession?.sessionId) : undefined
  const navigate = (next: Page) => { setPage(next); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const startSession = (routineId: string) => {
    const routine = state.routines.find((item) => item.id === routineId); if (!routine) return
    const now = new Date().toISOString(); const session: WorkoutSession = { id: uid('session'), routineId, date: isoDate(), startedAt: now, durationSeconds: 0, notes: '', completed: false, exercises: [...routine.exercises].sort((a, b) => a.order - b.order).map((item) => ({ exerciseId: item.exerciseId, sets: Array.from({ length: item.targetSets }, (_, index) => ({ id: uid('set'), exerciseId: item.exerciseId, setNumber: index + 1, reps: 0, weight: item.startingWeight ?? 0, completed: false, timestamp: now })) })) }
    setState((current) => ({ ...current, sessions: [...current.sessions.filter((item) => item.id !== session.id), session], activeSession: { sessionId: session.id, startedAt: now, pausedSeconds: 0 } })); setSelectedSession(session.id); navigate('session'); setToast('Entrenamiento iniciado')
  }
  const updateSession = (sessionId: string, updater: (session: WorkoutSession) => WorkoutSession) => setState((current) => ({ ...current, sessions: current.sessions.map((session) => session.id === sessionId ? updater(session) : session) }))
  const finishSession = (sessionId: string) => {
    const current = state.sessions.find((session) => session.id === sessionId); if (!current || !state.activeSession) return
    const endedAt = new Date().toISOString(); const durationSeconds = Math.max(0, Math.round((Date.parse(endedAt) - Date.parse(state.activeSession.startedAt)) / 1000) - state.activeSession.pausedSeconds)
    const finished = { ...current, endedAt, durationSeconds, completed: true }; const records = finished.exercises.flatMap((item) => detectNewRecords(item.exerciseId, item.sets, state.records, finished.date, finished.id));
    setState((old) => ({ ...old, sessions: old.sessions.map((session) => session.id === sessionId ? finished : session), records: [...old.records, ...records], activeSession: undefined })); setToast(records.length ? `¡Nuevo PR! ${records.length} récord${records.length > 1 ? 's' : ''} guardado${records.length > 1 ? 's' : ''}` : 'Entrenamiento guardado'); navigate('dashboard')
  }
  const deleteSession = (sessionId: string) => {
    const target = state.sessions.find((session) => session.id === sessionId); if (!target) return
    const exerciseIds = new Set(target.exercises.map((item) => item.exerciseId))
    setState((old) => ({ ...old, sessions: old.sessions.filter((session) => session.id !== sessionId), records: old.records.filter((record) => record.sessionId ? record.sessionId !== sessionId : !(record.date === target.date && exerciseIds.has(record.exerciseId))), activeSession: old.activeSession?.sessionId === sessionId ? undefined : old.activeSession }))
    setSelectedSession((current) => current === sessionId ? undefined : current); setToast('Entrenamiento eliminado')
  }

  if (!ready) return <div className="splash"><div className="brand-mark">G</div><p>Cargando tu espacio de entrenamiento…</p></div>
  return <div className="app-shell">
    <header className="topbar"><button className="brand brand-button" onClick={() => navigate('dashboard')} aria-label="Ir al inicio"><span className="brand-mark">G</span><span>Gym<span>Flow</span></span></button><div className="top-actions"><button className="icon-button" onClick={() => navigate('settings')} aria-label="Configuración"><Settings size={19} /></button></div></header>
    <main className="page-wrap">{page === 'dashboard' && <Dashboard state={state} activeSession={activeSession} navigate={navigate} startSession={startSession} />}{page === 'routines' && <Routines state={state} setState={setState} startSession={startSession} navigate={navigate} />}{page === 'session' && activeSession && <SessionView state={state} session={activeSession} updateSession={updateSession} finishSession={finishSession} navigate={navigate} />}{page === 'calendar' && <CalendarView state={state} onSession={(id) => { setSelectedSession(id); navigate('history') }} navigate={navigate} />}{page === 'progress' && <Progress state={state} setState={setState} />}{page === 'technique' && <TechniqueView state={state} setState={setState} />}{page === 'history' && <HistoryView state={state} selectedSession={selectedSession} deleteSession={deleteSession} navigate={navigate} />}{page === 'settings' && <SettingsView state={state} setState={setState} />}</main>
    {toast && <div className="toast"><Check size={17} />{toast}</div>}
  </div>
}

function PageTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="page-title"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1>{description && <p className="muted">{description}</p>}</div>{action}</div> }
function EmptyState({ icon: Icon, title, text, action }: { icon: typeof Dumbbell; title: string; text: string; action?: React.ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Icon size={25} /></div><h3>{title}</h3><p className="muted">{text}</p>{action}</div> }
function BackHomeButton({ navigate }: { navigate: (page: Page) => void }) { return <button className="text-button back-home-link" onClick={() => navigate('dashboard')}><ArrowLeft size={15} /> Inicio</button> }
function Dashboard({ state, activeSession, navigate, startSession }: { state: AppState; activeSession?: WorkoutSession; navigate: (page: Page) => void; startSession: (id: string) => void }) {
  const [selectedRoutineId, setSelectedRoutineId] = useState(state.routines[0]?.id ?? '')
  const [now, setNow] = useState(Date.now())
  const weekSessions = state.sessions.filter((session) => session.completed && isSameWeek(session.date))
  const weekTime = weekSessions.reduce((sum, session) => sum + session.durationSeconds, 0)
  const selectedRoutine = state.routines.find((routine) => routine.id === selectedRoutineId) ?? state.routines[0]
  const activeRoutine = activeSession ? state.routines.find((routine) => routine.id === activeSession.routineId) : undefined
  const active = state.activeSession
  const activeElapsed = active ? Math.max(0, Math.floor((now - Date.parse(active.startedAt)) / 1000) - active.pausedSeconds) : 0
  const exerciseName = (id: string) => state.exercises.find((exercise) => exercise.id === id)?.name ?? 'Ejercicio'

  useEffect(() => {
    if (!active) return
    const timer = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(timer)
  }, [active])

  useEffect(() => {
    if (!state.routines.some((routine) => routine.id === selectedRoutineId)) setSelectedRoutineId(state.routines[0]?.id ?? '')
  }, [selectedRoutineId, state.routines])

  return <>
    <PageTitle eyebrow="HOY" title="Tu entrenamiento" description="Elegí un día, mirá tu plan y empezá." />
    {activeSession && <section className="active-session-strip card"><div className="active-session-copy"><span className="pulse-dot" /><div><p className="eyebrow lime">SESIÓN EN CURSO</p><strong>{activeRoutine?.name ?? 'Rutina'}</strong></div></div><div className="active-session-time"><span>TIEMPO</span><strong>{formatDuration(activeElapsed)}</strong></div><button className="button primary" onClick={() => navigate('session')}><Play size={16} fill="currentColor" /> Continuar</button></section>}
    {state.routines.length ? <section className="training-board card"><div className="training-board-heading"><div><p className="eyebrow lime">PLAN DE ENTRENAMIENTO</p><h2>¿Qué toca hoy?</h2></div><button className="text-button" onClick={() => navigate('routines')}>Editar días</button></div><div className="routine-tabs" role="tablist" aria-label="Días de entrenamiento">{state.routines.map((routine, index) => <button key={routine.id} className={routine.id === selectedRoutine?.id ? 'routine-tab selected' : 'routine-tab'} onClick={() => setSelectedRoutineId(routine.id)} role="tab" aria-selected={routine.id === selectedRoutine?.id}><span>Día {String(index + 1).padStart(2, '0')}</span><strong>{routine.name}</strong><small>{routine.exercises.length} ejercicios</small></button>)}</div>{selectedRoutine && <div className="selected-routine"><div className="selected-routine-heading"><div><span className="routine-tag">{selectedRoutine.exercises.length} ejercicios</span><h3>{selectedRoutine.name}</h3><p className="muted">{selectedRoutine.description}</p></div><button className="button primary quick-start-button" onClick={() => activeSession ? navigate('session') : startSession(selectedRoutine.id)}><Play size={16} fill="currentColor" /> {activeSession ? 'Continuar sesión' : 'Comenzar rápido'}</button></div>{selectedRoutine.exercises.length ? <div className="exercise-sheet"><div className="exercise-sheet-head"><span>Ejercicio</span><span>Series / reps</span><span>Carga inicial</span></div>{selectedRoutine.exercises.slice().sort((a, b) => a.order - b.order).map((item, index) => <div className="exercise-sheet-row" key={`${selectedRoutine.id}-${item.exerciseId}-${index}`}><div><span className="exercise-number">{String(index + 1).padStart(2, '0')}</span><strong>{exerciseName(item.exerciseId)}</strong></div><small>{item.targetSets} × {item.repMin}-{item.repMax}</small><small>{item.startingWeight ? `${formatNumber(item.startingWeight)} kg` : item.startingLoad ?? '—'}</small></div>)}</div> : <p className="muted empty-routine-note">Este día todavía no tiene ejercicios.</p>}</div>}</section> : <section className="section-block"><EmptyState icon={Dumbbell} title="Todavía no tenés una rutina" text="Importá tu Excel o creá una rutina corta para empezar." action={<button className="button secondary" onClick={() => navigate('routines')}>Agregar rutina</button>} /></section>}
    <div className="dashboard-calendar"><MiniCalendar state={state} weekSessions={weekSessions} weekTime={weekTime} onOpen={() => navigate('calendar')} /></div>
  </>
}

function MiniCalendar({ state, weekSessions, weekTime, onOpen }: { state: AppState; weekSessions: WorkoutSession[]; weekTime: number; onOpen: () => void }) {
  const [month, setMonth] = useState(new Date())
  const year = month.getFullYear()
  const monthIndex = month.getMonth()
  const first = new Date(year, monthIndex, 1)
  const days = new Date(year, monthIndex + 1, 0).getDate()
  const offset = (first.getDay() + 6) % 7
  const cells = Array.from({ length: offset + days }, (_, index) => index < offset ? undefined : index - offset + 1)
  const byDate = new Map(state.sessions.filter((session) => session.completed).map((session) => [session.date, session]))
  const monthLabel = new Intl.DateTimeFormat('es-AR', { month: 'long', year: 'numeric' }).format(month)

  return <section className="mini-calendar card"><div className="mini-calendar-top"><div><p className="eyebrow">CONSTANCIA</p><h2>Calendario</h2></div><button className="text-button" onClick={onOpen}>Ver completo <ChevronDown className="rotate-90" size={15} /></button></div><div className="mini-calendar-month"><button className="icon-button subtle" onClick={() => setMonth(new Date(year, monthIndex - 1, 1))} aria-label="Mes anterior"><ChevronDown className="rotate-90-left" size={16} /></button><strong>{monthLabel}</strong><button className="icon-button subtle" onClick={() => setMonth(new Date(year, monthIndex + 1, 1))} aria-label="Mes siguiente"><ChevronDown className="rotate-90" size={16} /></button></div><div className="mini-calendar-weekdays">{['L', 'M', 'X', 'J', 'V', 'S', 'D'].map((day) => <span key={day}>{day}</span>)}</div><div className="mini-calendar-grid">{cells.map((day, index) => { const date = day ? `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}` : ''; const session = byDate.get(date); return <button key={index} className={session ? 'mini-calendar-day trained' : date === isoDate() ? 'mini-calendar-day today' : 'mini-calendar-day'} disabled={!session} aria-label={session ? `Sesión del ${date}` : day ? `Día ${day}` : undefined}><span>{day}</span>{session && <Check size={11} />}</button> })}</div><div className="mini-calendar-footer"><span><i className="legend-dot trained-dot" /> {weekSessions.length} esta semana</span><span>{formatDuration(weekTime)}</span></div></section>
}
function MetricCard({ icon: Icon, label, value, suffix, accent }: { icon: typeof Activity; label: string; value: string; suffix: string; accent: string }) { return <div className={`metric-card ${accent}`}><div className="metric-icon"><Icon size={18} /></div><small>{label}</small><strong>{value}</strong><span>{suffix}</span></div> }

function Routines({ state, setState, startSession, navigate }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>>; startSession: (id: string) => void; navigate: (page: Page) => void }) {
  const [editing, setEditing] = useState<string>(); const [draftName, setDraftName] = useState(''); const [draftDescription, setDraftDescription] = useState(''); const [importMessage, setImportMessage] = useState(''); const [importError, setImportError] = useState('')
  const openEditor = (routine?: WorkoutRoutine) => { if (routine) { setEditing(routine.id); setDraftName(routine.name); setDraftDescription(routine.description) } else { const id = uid('routine'); setState((old) => ({ ...old, routines: [...old.routines, { id, name: 'Nueva rutina', description: 'Una rutina a tu medida', createdAt: new Date().toISOString(), exercises: [] }] })); setEditing(id); setDraftName('Nueva rutina'); setDraftDescription('Una rutina a tu medida') } }
  const updateRoutine = (routineId: string, updater: (routine: WorkoutRoutine) => WorkoutRoutine) => setState((old) => ({ ...old, routines: old.routines.map((routine) => routine.id === routineId ? updater(routine) : routine) }))
  const remove = (id: string) => setState((old) => ({ ...old, routines: old.routines.filter((routine) => routine.id !== id) }))
  const duplicate = (routine: WorkoutRoutine) => setState((old) => ({ ...old, routines: [...old.routines, { ...routine, id: uid('routine'), name: `${routine.name} copia`, createdAt: new Date().toISOString(), exercises: routine.exercises.map((item) => ({ ...item })) }] }))
  const importExcel = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; setImportMessage(''); setImportError(''); try { const result = await parseWorkoutWorkbook(file); setState((old) => ({ ...old, routines: [...old.routines, ...result.routines], exercises: [...old.exercises, ...result.exercises.filter((exercise) => !old.exercises.some((current) => current.id === exercise.id || current.name.toLowerCase() === exercise.name.toLowerCase()))] })); setImportMessage(`${result.routines.length} rutinas importadas desde ${file.name}.`); } catch (error) { setImportError(error instanceof Error ? error.message : 'No se pudo leer el Excel.') } }
  return <><PageTitle eyebrow="ENTRENAMIENTO" title="Tus rutinas" description="Diseñá sesiones que puedas repetir y mejorar." action={<div className="page-title-actions"><BackHomeButton navigate={navigate} /><label className="button secondary import-button"><Upload size={16} /> Importar Excel<input type="file" accept=".xlsx,.xls" hidden onChange={importExcel} /></label><button className="button primary" onClick={() => openEditor()}><Plus size={17} /> Nueva rutina</button></div>} />{(importMessage || importError) && <p className={importError ? 'import-feedback error-text' : 'import-feedback'}>{importError || importMessage}</p>}<div className="routine-list">{state.routines.map((routine) => editing === routine.id ? <RoutineEditor key={routine.id} routine={routine} state={state} setState={setState} draftName={draftName} setDraftName={setDraftName} draftDescription={draftDescription} setDraftDescription={setDraftDescription} onSave={() => { updateRoutine(routine.id, (item) => ({ ...item, name: draftName.trim() || 'Sin nombre', description: draftDescription })); setEditing(undefined) }} onCancel={() => setEditing(undefined)} /> : <RoutineCard key={routine.id} routine={routine} state={state} onStart={() => startSession(routine.id)} onEdit={() => openEditor(routine)} onDelete={() => remove(routine.id)} onDuplicate={() => duplicate(routine)} />)}</div>{!state.routines.length && <EmptyState icon={Dumbbell} title="Creá tu primera rutina" text="Armá una sesión en menos de un minuto." action={<button className="button primary" onClick={() => openEditor()}>Crear rutina</button>} />}</>
}
function RoutineCard({ routine, state, onStart, onEdit, onDelete, onDuplicate }: { routine: WorkoutRoutine; state: AppState; onStart: () => void; onEdit: () => void; onDelete: () => void; onDuplicate: () => void }) { return <article className="routine-card card"><div className="routine-card-top"><div><span className="routine-tag">{routine.exercises.length} ejercicios</span><h2>{routine.name}</h2><p className="muted">{routine.description}</p></div><button className="icon-button subtle" onClick={onEdit} aria-label="Editar rutina"><Settings size={18} /></button></div><div className="routine-preview">{routine.exercises.slice(0, 4).map((item) => <div key={item.exerciseId}><span className="exercise-dot" /><span>{state.exercises.find((exercise) => exercise.id === item.exerciseId)?.name ?? 'Ejercicio'}</span><small>{item.targetSets} × {item.repMin}-{item.repMax}</small></div>)}{routine.exercises.length > 4 && <small className="muted">+ {routine.exercises.length - 4} ejercicios más</small>}</div><div className="routine-actions"><button className="button primary grow" onClick={onStart}><Play size={16} fill="currentColor" /> Empezar</button><button className="icon-button subtle" onClick={onDuplicate} title="Duplicar"><RotateCcw size={17} /></button><button className="icon-button danger" onClick={onDelete} title="Eliminar"><Trash2 size={17} /></button></div></article> }
function RoutineEditor({ routine, state, setState, draftName, setDraftName, draftDescription, setDraftDescription, onSave, onCancel }: { routine: WorkoutRoutine; state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>>; draftName: string; setDraftName: (value: string) => void; draftDescription: string; setDraftDescription: (value: string) => void; onSave: () => void; onCancel: () => void }) { const [exerciseId, setExerciseId] = useState(state.exercises[0]?.id ?? ''); const add = () => { if (!exerciseId) return; setState((old) => ({ ...old, routines: old.routines.map((item) => item.id === routine.id ? { ...item, exercises: [...item.exercises, { exerciseId, order: item.exercises.length, targetSets: 3, repMin: 8, repMax: 12, restSeconds: 90 }] } : item) })); setExerciseId('') }; const updateItem = (index: number, patch: Partial<RoutineExercise>) => setState((old) => ({ ...old, routines: old.routines.map((item) => item.id === routine.id ? { ...item, exercises: item.exercises.map((exercise, itemIndex) => itemIndex === index ? { ...exercise, ...patch } : exercise) } : item) })); const removeItem = (index: number) => setState((old) => ({ ...old, routines: old.routines.map((item) => item.id === routine.id ? { ...item, exercises: item.exercises.filter((_, itemIndex) => itemIndex !== index) } : item) })); return <article className="editor-card card"><div className="editor-header"><div><p className="eyebrow">EDITANDO RUTINA</p><h2>Armá tu sesión</h2></div><button className="icon-button subtle" onClick={onCancel}><X size={19} /></button></div><label>Nombre<input value={draftName} onChange={(event) => setDraftName(event.target.value)} /></label><label>Descripción<textarea value={draftDescription} onChange={(event) => setDraftDescription(event.target.value)} rows={2} /></label><div className="editor-exercises"><div className="section-heading compact"><h3>Ejercicios</h3><span className="muted">{routine.exercises.length} agregados</span></div>{routine.exercises.map((item, index) => <div className="editor-exercise" key={`${item.exerciseId}-${index}`}><div className="exercise-number">{index + 1}</div><div className="exercise-edit-main"><strong>{state.exercises.find((exercise) => exercise.id === item.exerciseId)?.name}</strong><div className="inline-fields"><label>Series<input type="number" min="1" value={item.targetSets} onChange={(event) => updateItem(index, { targetSets: Number(event.target.value) })} /></label><label>Reps<input type="text" value={`${item.repMin}-${item.repMax}`} onChange={(event) => { const [min, max] = event.target.value.split('-').map(Number); updateItem(index, { repMin: min || item.repMin, repMax: max || item.repMax }) }} /></label><label>Descanso<input type="number" min="0" value={item.restSeconds} onChange={(event) => updateItem(index, { restSeconds: Number(event.target.value) })} /></label></div></div><button className="icon-button danger" onClick={() => removeItem(index)}><Trash2 size={16} /></button></div>)}<div className="add-exercise"><select value={exerciseId} onChange={(event) => setExerciseId(event.target.value)}><option value="">Elegir ejercicio…</option>{state.exercises.map((exercise) => <option key={exercise.id} value={exercise.id}>{exercise.name}</option>)}</select><button className="button secondary" onClick={add}><Plus size={16} /> Agregar</button></div></div><div className="editor-footer"><button className="button ghost" onClick={onCancel}>Cancelar</button><button className="button primary" onClick={onSave}><Check size={16} /> Guardar rutina</button></div></article> }

function SessionView({ state, session, updateSession, finishSession, navigate }: { state: AppState; session: WorkoutSession; updateSession: (id: string, updater: (session: WorkoutSession) => WorkoutSession) => void; finishSession: (id: string) => void; navigate: (page: Page) => void }) {
  const [now, setNow] = useState(Date.now())
  const [rest, setRest] = useState<number>()
  const [paused, setPaused] = useState(false)
  const [confirmFinish, setConfirmFinish] = useState(false)

  useEffect(() => {
    const timer = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(timer)
  }, [])

  const active = state.activeSession
  const elapsed = active ? Math.max(0, Math.floor((now - Date.parse(active.startedAt)) / 1000) - active.pausedSeconds) : 0
  const routine = state.routines.find((item) => item.id === session.routineId)
  const allDone = session.exercises.length > 0 && session.exercises.every((item) => item.sets.some((set) => set.completed))

  const setValue = (exerciseId: string, setId: string, patch: Partial<ExerciseSet>) => updateSession(session.id, (item) => ({ ...item, exercises: item.exercises.map((exercise) => exercise.exerciseId === exerciseId ? { ...exercise, sets: exercise.sets.map((set) => set.id === setId ? { ...set, ...patch, timestamp: new Date().toISOString() } : set) } : exercise) }))
  const setExerciseWeight = (exerciseId: string, weight: number) => updateSession(session.id, (item) => ({ ...item, exercises: item.exercises.map((exercise) => exercise.exerciseId === exerciseId ? { ...exercise, sets: exercise.sets.map((set) => ({ ...set, weight })) } : exercise) }))
  const toggleSet = (exerciseId: string, set: ExerciseSet) => {
    const completed = !set.completed
    setValue(exerciseId, set.id, { completed })
    if (completed && state.settings.autoRest) setRest(routine?.exercises.find((item) => item.exerciseId === exerciseId)?.restSeconds ?? 90)
  }
  const addSet = (exerciseId: string) => updateSession(session.id, (item) => ({ ...item, exercises: item.exercises.map((exercise) => exercise.exerciseId === exerciseId ? { ...exercise, sets: [...exercise.sets, { id: uid('set'), exerciseId, setNumber: exercise.sets.length + 1, reps: 0, weight: exercise.sets[0]?.weight ?? 0, completed: false, timestamp: new Date().toISOString() }] } : exercise) }))
  const removeSet = (exerciseId: string, setId: string) => updateSession(session.id, (item) => ({ ...item, exercises: item.exercises.map((exercise) => exercise.exerciseId === exerciseId ? { ...exercise, sets: exercise.sets.filter((set) => set.id !== setId).map((set, index) => ({ ...set, setNumber: index + 1 })) } : exercise) }))

  return <div className="session-page">
    <div className="session-top"><button className="back-button" onClick={() => navigate('dashboard')}><ArrowLeft size={18} /> Salir</button><div className="session-timer"><span>TIEMPO</span><strong>{formatDuration(elapsed)}</strong></div><button className="button finish-button" onClick={() => setConfirmFinish(true)}><Square size={14} fill="currentColor" /> Finalizar</button></div>
    <div className="session-heading"><p className="eyebrow lime">EN CURSO</p><h1>{routine?.name}</h1><p className="muted">{session.exercises.filter((item) => item.sets.some((set) => set.completed)).length} de {session.exercises.length} ejercicios con series registradas</p></div>
    {session.exercises.map((item, index) => {
      const exercise = state.exercises.find((candidate) => candidate.id === item.exerciseId)
      const prescription = routine?.exercises.find((candidate) => candidate.exerciseId === item.exerciseId)
      const exerciseWeight = item.sets[0]?.weight ?? 0
      return <section className="session-exercise card" key={item.exerciseId}>
        <div className="session-exercise-heading"><div><span className="exercise-index">{String(index + 1).padStart(2, '0')}</span><h2>{exercise?.name}</h2><p className="muted">{prescription ? prescription.targetSets + ' series · ' + prescription.repMin + '-' + prescription.repMax + ' reps' : 'Registrá las series de este ejercicio'}</p></div><label className="exercise-weight-field"><span>PESO {state.settings.unit.toUpperCase()}</span><input type="number" min="0" inputMode="decimal" placeholder="0" value={exerciseWeight || ''} onChange={(event) => setExerciseWeight(item.exerciseId, Number(event.target.value))} /></label></div>
        <p className="same-weight-note">Mismo peso para todas las series</p>
        <div className="set-header same-weight"><span>SERIE</span><span>REPS</span><span></span><span></span></div>
        {item.sets.map((set) => <div className={set.completed ? 'set-row same-weight completed' : 'set-row same-weight'} key={set.id}><strong>{set.setNumber}</strong><input type="number" min="0" inputMode="numeric" placeholder="0" value={set.reps || ''} onChange={(event) => setValue(item.exerciseId, set.id, { reps: Number(event.target.value) })} /><button className={set.completed ? 'complete-set active' : 'complete-set'} onClick={() => toggleSet(item.exerciseId, set)} aria-label="Completar serie"><Check size={17} /></button><button className="row-delete" onClick={() => removeSet(item.exerciseId, set.id)} aria-label="Eliminar serie"><X size={14} /></button></div>)}
        <button className="add-set" onClick={() => addSet(item.exerciseId)}><Plus size={15} /> Agregar serie</button>
      </section>
    })}
    <div className="session-note"><label><span>Notas de la sesión</span><textarea value={session.notes} placeholder="¿Cómo te sentiste?" onChange={(event) => updateSession(session.id, (item) => ({ ...item, notes: event.target.value }))} rows={2} /></label></div>
    <button className="button lime-button wide" onClick={() => setConfirmFinish(true)} disabled={!allDone}><Check size={18} /> {allDone ? 'Guardar y finalizar' : 'Completá al menos una serie por ejercicio'}</button>
    {rest !== undefined && <RestTimer seconds={rest} setSeconds={setRest} onClose={() => setRest(undefined)} />}
    {confirmFinish && <div className="modal-backdrop"><div className="confirm-modal card"><div className="modal-icon"><Check /></div><h2>¿Terminaste?</h2><p className="muted">Se guardarán {session.exercises.reduce((sum, item) => sum + item.sets.filter((set) => set.completed).length, 0)} series y el tiempo de esta sesión.</p><div className="modal-actions"><button className="button ghost" onClick={() => setConfirmFinish(false)}>Seguir entrenando</button><button className="button primary" onClick={() => finishSession(session.id)}>Finalizar sesión</button></div></div></div>}
    {paused && <button className="pause-overlay" onClick={() => setPaused(false)}><Play size={18} /> Continuar sesión</button>}
    <button className="floating-pause" onClick={() => setPaused((value) => !value)}>{paused ? <Play size={18} /> : <Pause size={18} />}</button>
  </div>
}
function RestTimer({ seconds, setSeconds, onClose }: { seconds: number; setSeconds: React.Dispatch<React.SetStateAction<number | undefined>>; onClose: () => void }) { useEffect(() => { if (seconds <= 0) { if (navigator.vibrate) navigator.vibrate([100, 80, 100]); return } const timer = window.setTimeout(() => setSeconds((value) => value === undefined ? undefined : value - 1), 1000); return () => window.clearTimeout(timer) }, [seconds, setSeconds]); return <div className="rest-timer"><div><span>DESCANSO</span><strong>{formatTimerShort(seconds)}</strong></div><div className="rest-actions"><button onClick={() => setSeconds((value) => value === undefined ? undefined : value + 15)}>+15</button><button onClick={() => setSeconds((value) => value === undefined ? undefined : Math.max(0, value - 15))}>−15</button><button onClick={onClose}><X size={16} /></button></div></div> }

function CalendarView({ state, onSession, navigate }: { state: AppState; onSession: (id: string) => void; navigate: (page: Page) => void }) { const [month, setMonth] = useState(() => { const today = new Date(); return new Date(today.getFullYear(), today.getMonth(), 1) }); const year = month.getFullYear(); const monthIndex = month.getMonth(); const first = new Date(year, monthIndex, 1); const days = new Date(year, monthIndex + 1, 0).getDate(); const offset = (first.getDay() + 6) % 7; const sessions = state.sessions.filter((session) => session.completed); const byDate = new Map(sessions.map((session) => [session.date, session])); const cells = Array.from({ length: offset + days }, (_, index) => index < offset ? undefined : index - offset + 1); return <><PageTitle eyebrow="CONSTANCIA" title="Calendario" description="Cada marca cuenta. Mirá cómo venís." action={<div className="page-title-actions"><BackHomeButton navigate={navigate} /><div className="streak-pill"><Flame size={16} /> {sessions.length} sesiones</div></div>} /><section className="calendar-card card"><div className="calendar-header"><button className="icon-button subtle" onClick={() => setMonth(new Date(year, monthIndex - 1, 1))}><ChevronDown className="rotate-90-left" size={18} /></button><h2>{new Intl.DateTimeFormat('es-AR', { month: 'long', year: 'numeric' }).format(month)}</h2><button className="icon-button subtle" onClick={() => setMonth(new Date(year, monthIndex + 1, 1))}><ChevronDown className="rotate-90" size={18} /></button></div><div className="calendar-weekdays">{['L','M','X','J','V','S','D'].map((day) => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{cells.map((day, index) => { const date = day ? [String(year), String(monthIndex + 1).padStart(2, '0'), String(day).padStart(2, '0')].join('-') : ''; const session = byDate.get(date); return <button key={index} className={session ? 'calendar-day trained' : date === isoDate() ? 'calendar-day today' : 'calendar-day'} disabled={!session} onClick={() => session && onSession(session.id)}><span>{day}</span>{session && <Check size={13} />}</button> })}</div><div className="calendar-legend"><span><i className="legend-dot trained-dot" /> Entrenamiento completado</span><span><i className="legend-dot today-dot" /> Hoy</span></div></section><div className="calendar-insight"><div className="insight-icon"><Zap size={18} /></div><div><strong>La constancia gana</strong><p className="muted">Este mes completaste {sessions.filter((session) => session.date.startsWith(String(year) + '-' + String(monthIndex + 1).padStart(2, '0'))).length} entrenamientos. Volvé mañana para mantener el ritmo.</p></div></div></> }
function Progress({ state, setState }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>> }) { const [selectedExercise, setSelectedExercise] = useState(state.exercises[0]?.id ?? ''); const exercise = state.exercises.find((item) => item.id === selectedExercise); const sessions = state.sessions.filter((session) => session.completed && session.exercises.some((item) => item.exerciseId === selectedExercise)).sort((a, b) => a.date.localeCompare(b.date)); const records = state.records.filter((record) => record.exerciseId === selectedExercise); const maxWeight = records.filter((record) => record.type === 'weight').sort((a, b) => b.value - a.value)[0]; const maxVolume = records.filter((record) => record.type === 'volume').sort((a, b) => b.value - a.value)[0]; const points = sessions.slice(-7).map((session) => { const sets = session.exercises.find((item) => item.exerciseId === selectedExercise)?.sets.filter((set) => set.completed) ?? []; return { date: session.date, value: Math.max(...sets.map((set) => set.weight), 0) } }); const maxPoint = Math.max(...points.map((point) => point.value), 1); return <><PageTitle eyebrow="DATOS REALES" title="Progreso" description="Pequeñas mejoras, acumuladas." /><div className="select-wrap"><Dumbbell size={17} /><select value={selectedExercise} onChange={(event) => setSelectedExercise(event.target.value)}>{state.exercises.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><ChevronDown size={16} /></div>{exercise && <><div className="progress-hero card"><div><span className="routine-tag">{exercise.muscleGroup}</span><h2>{exercise.name}</h2><p className="muted">Tu evolución de carga máxima registrada.</p></div><div className="progress-big"><span>PR actual</span><strong>{maxWeight ? `${formatNumber(maxWeight.value)} kg` : '—'}</strong></div></div><div className="metric-grid two"><MetricCard icon={Trophy} label="Mayor peso" value={maxWeight ? formatNumber(maxWeight.value) : '—'} suffix={maxWeight ? 'kg' : 'sin datos'} accent="lime" /><MetricCard icon={Activity} label="Mayor volumen" value={maxVolume ? formatNumber(maxVolume.value) : '—'} suffix={maxVolume ? 'kg total' : 'sin datos'} accent="blue" /></div><section className="section-block"><div className="section-heading"><div><p className="eyebrow">CARGA MÁXIMA</p><h2>Últimas sesiones</h2></div></div><div className="chart-card card">{points.length ? <><div className="bar-chart">{points.map((point) => <div className="chart-col" key={point.date}><div className="bar-value">{point.value ? `${formatNumber(point.value)}` : '—'}</div><div className="bar-track"><div className="bar-fill" style={{ height: `${Math.max(8, (point.value / maxPoint) * 100)}%` }} /></div><small>{formatDate(point.date)}</small></div>)}</div><div className="chart-footer"><span><i className="legend-dot trained-dot" /> Peso utilizado por sesión</span><span>{sessions.length} sesiones analizadas</span></div></> : <EmptyState icon={BarChart3} title="Aún no hay datos" text="Completá algunas series para ver tu tendencia." />}</div></section></>}</> }

function BodyWeightPanel({ state, setState }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>> }) { const [weight, setWeight] = useState(''); const entries = [...state.bodyWeight].sort((a, b) => a.date.localeCompare(b.date)); const latest = entries.at(-1); const previous = entries.at(-2); const addEntry = () => { const value = Number(weight); if (!value || value < 20 || value > 300) return; const entry: BodyWeightEntry = { id: uid('weight'), date: isoDate(), weight: value }; setState((old) => ({ ...old, bodyWeight: [...old.bodyWeight.filter((item) => item.date !== entry.date), entry] })); setWeight('') }; const min = Math.min(...entries.map((entry) => entry.weight), latest?.weight ?? 0); const max = Math.max(...entries.map((entry) => entry.weight), latest?.weight ?? 1); return <section className="section-block"><div className="section-heading"><div><p className="eyebrow">PESO CORPORAL</p><h2>Evolución personal</h2></div>{latest && <span className="routine-tag">Actual: {formatNumber(latest.weight)} kg</span>}</div><div className="bodyweight-card card"><div className="weight-form"><input type="number" min="20" max="300" step="0.1" placeholder="Ej. 78.5" value={weight} onChange={(event) => setWeight(event.target.value)} /><button className="button primary" onClick={addEntry}><Plus size={16} /> Registrar</button></div>{latest && <p className="muted weight-delta">{previous ? `${latest.weight - previous.weight >= 0 ? '+' : ''}${formatNumber(latest.weight - previous.weight)} kg desde tu registro anterior` : 'Primer registro guardado'}</p>}{entries.length > 1 && <div className="weight-chart">{entries.slice(-8).map((entry) => <div className="weight-point" key={entry.id}><span style={{ bottom: `${max === min ? 50 : ((entry.weight - min) / (max - min)) * 72 + 15}%` }}>{formatNumber(entry.weight)}</span><i style={{ bottom: `${max === min ? 50 : ((entry.weight - min) / (max - min)) * 72 + 15}%` }} /><small>{formatDate(entry.date)}</small></div>)}</div>}{!entries.length && <p className="muted">Registrá tu peso para empezar a ver la evolución.</p>}</div></section> }

function HistoryView({ state, selectedSession, deleteSession, navigate }: { state: AppState; selectedSession?: string; deleteSession: (id: string) => void; navigate: (page: Page) => void }) {
  const [filter, setFilter] = useState('')
  const [open, setOpen] = useState(selectedSession)
  const [deleteTarget, setDeleteTarget] = useState<WorkoutSession>()
  const sessions = state.sessions.filter((session) => session.completed && (!filter || state.routines.find((routine) => routine.id === session.routineId)?.name.toLowerCase().includes(filter.toLowerCase()) || session.date.includes(filter))).sort((a, b) => b.date.localeCompare(a.date))

  return <>
    <PageTitle eyebrow="TODO REGISTRADO" title="Historial" description="Revisá tus sesiones y corregí las que estén mal cargadas." action={<BackHomeButton navigate={navigate} />} />
    <div className="search-box"><History size={17} /><input placeholder="Buscar por rutina o fecha…" value={filter} onChange={(event) => setFilter(event.target.value)} /></div>
    <div className="history-list">{sessions.map((session) => {
      const routine = state.routines.find((item) => item.id === session.routineId)
      return <article className="history-card card" key={session.id}>
        <div className="history-summary-row"><button className="history-summary" onClick={() => setOpen(open === session.id ? undefined : session.id)}><div className="history-date"><strong>{new Date(session.date + 'T12:00:00').getDate()}</strong><span>{new Intl.DateTimeFormat('es-AR', { month: 'short' }).format(new Date(session.date + 'T12:00:00'))}</span></div><div><h3>{routine?.name ?? 'Rutina eliminada'}</h3><p className="muted">{formatDuration(session.durationSeconds)} · {session.exercises.reduce((sum, item) => sum + item.sets.filter((set) => set.completed).length, 0)} series</p></div><ChevronDown className={open === session.id ? 'chevron-up' : ''} size={18} /></button><button className="history-delete" onClick={() => setDeleteTarget(session)} aria-label="Eliminar entrenamiento"><Trash2 size={16} /></button></div>
        {open === session.id && <div className="history-details">{session.exercises.map((item) => <div key={item.exerciseId}><strong>{state.exercises.find((exercise) => exercise.id === item.exerciseId)?.name}</strong><div className="history-sets">{item.sets.filter((set) => set.completed).map((set) => <span key={set.id}>{formatNumber(set.weight)} kg × {set.reps}</span>)}</div></div>)}{session.notes && <p className="note-card">“{session.notes}”</p>}</div>}
      </article>
    })}</div>
    {!sessions.length && <EmptyState icon={History} title="No hay sesiones todavía" text="Tus entrenamientos finalizados van a aparecer acá." />}
    {deleteTarget && <div className="modal-backdrop"><div className="confirm-modal card"><div className="modal-icon danger"><Trash2 /></div><h2>¿Eliminar entrenamiento?</h2><p className="muted">Se eliminará la sesión del {formatDate(deleteTarget.date)} y sus récords asociados.</p><div className="modal-actions"><button className="button ghost" onClick={() => setDeleteTarget(undefined)}>Cancelar</button><button className="button delete-button" onClick={() => { deleteSession(deleteTarget.id); setDeleteTarget(undefined) }}>Eliminar entrenamiento</button></div></div></div>}
  </>
}

// eslint-disable-next-line react-hooks/exhaustive-deps
function TechniqueView({ state, setState }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>> }) { const supported = state.exercises.filter((exercise) => exercise.cameraEnabled); const [selected, setSelected] = useState(supported[0]?.id ?? 'curl'); const [started, setStarted] = useState(false); const [camera, setCamera] = useState<'user' | 'environment'>('environment'); const [skeleton, setSkeleton] = useState(state.settings.showSkeleton); const [feedback, setFeedback] = useState<TechniqueFeedback>(); const [error, setError] = useState(''); const videoRef = useRef<HTMLVideoElement>(null); const canvasRef = useRef<HTMLCanvasElement>(null); const analyzerRef = useRef<ExerciseAnalyzer | null>(null); const streamRef = useRef<MediaStream | null>(null); const animationRef = useRef<number | undefined>(undefined); const lastRepsRef = useRef(0); const exercise = state.exercises.find((item) => item.id === selected); useEffect(() => () => { streamRef.current?.getTracks().forEach((track) => track.stop()); if (animationRef.current) cancelAnimationFrame(animationRef.current) }, []); useEffect(() => { if (!started || !streamRef.current || !videoRef.current) return; videoRef.current.srcObject = streamRef.current; void videoRef.current.play().then(() => runPose()); }, [started]); const startCamera = async () => { setError(''); try { streamRef.current?.getTracks().forEach((track) => track.stop()); const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: camera, width: { ideal: 1280 }, height: { ideal: 720 } }, audio: false }); streamRef.current = stream; setStarted(true); analyzerRef.current = analyzers[selected.includes('squat') ? 'squat' : selected.includes('press') ? 'press' : 'curl'](); } catch (cameraError) { setError(cameraError instanceof DOMException && cameraError.name === 'NotAllowedError' ? 'Permiso de cámara rechazado. Habilitalo desde el navegador para analizar tu técnica.' : 'No se pudo acceder a la cámara en este dispositivo.'); } }; const runPose = async () => { if (!videoRef.current) return; let landmarker: { detectForVideo: (video: HTMLVideoElement, timestamp: number) => { landmarks?: Array<Array<{ x: number; y: number; z: number; visibility?: number }>> } } | undefined; try { const vision = await import('@mediapipe/tasks-vision'); const fileset = await vision.FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.22/wasm'); landmarker = await vision.PoseLandmarker.createFromOptions(fileset, { baseOptions: { modelAssetPath: 'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task', delegate: 'GPU' }, runningMode: 'VIDEO', numPoses: 1 }); } catch { setError('No se pudo cargar el modelo de pose. Podés seguir usando el modo cámara, pero sin medición de técnica.'); return } const names = ['nose','left_eye','right_eye','left_ear','right_ear','left_shoulder','right_shoulder','left_elbow','right_elbow','left_wrist','right_wrist','left_hip','right_hip','left_knee','right_knee','left_ankle','right_ankle','left_heel','right_heel','left_foot_index','right_foot_index']; const draw = () => { if (!videoRef.current || !landmarker || videoRef.current.readyState < 2) { animationRef.current = requestAnimationFrame(draw); return } const result = landmarker.detectForVideo(videoRef.current, performance.now()); const points = result.landmarks?.[0] ?? []; const landmarks: Landmark[] = points.map((point, index) => ({ name: names[index] ?? `point_${index}`, x: point.x, y: point.y, z: point.z, visibility: point.visibility ?? 1 })); const frame: PoseFrame = { landmarks, timestamp: performance.now() }; const next = analyzerRef.current?.analyze(frame); if (next) { setFeedback(next); if (next.reps > lastRepsRef.current) lastRepsRef.current = next.reps; } if (canvasRef.current && skeleton) drawSkeleton(canvasRef.current, videoRef.current, landmarks); animationRef.current = requestAnimationFrame(draw) }; draw() }; const stop = () => { streamRef.current?.getTracks().forEach((track) => track.stop()); streamRef.current = null; setStarted(false); analyzerRef.current = null; if (animationRef.current) cancelAnimationFrame(animationRef.current); if (feedback && exercise) { const analysis: TechniqueAnalysis = { id: uid('analysis'), exerciseId: exercise.id, date: isoDate(), reps: feedback.reps, quality: feedback.quality, metrics: feedback.metrics, errors: feedback.warnings, observations: [feedback.message] }; setState((old) => ({ ...old, analyses: [...old.analyses, analysis] })) } }; return <><PageTitle eyebrow="MODO ENTRENAMIENTO" title="Analizá tu técnica" description="Procesamiento local. El video no se guarda ni se envía." action={<div className="privacy-pill"><span className="lock-dot" /> Privado</div>} />{!started ? <><section className="technique-intro card"><div className="camera-icon-large"><Camera size={30} /></div><div><h2>Feedback en tiempo real</h2><p className="muted">Elegí un ejercicio, colocá el celular de costado y asegurate de que todo tu cuerpo entre en cuadro.</p></div></section><div className="exercise-picker"><p className="eyebrow">ELEGÍ UN EJERCICIO</p><div className="picker-grid">{supported.map((item) => <button className={item.id === selected ? 'picker-card selected' : 'picker-card'} key={item.id} onClick={() => setSelected(item.id)}><span className="picker-icon"><Activity size={19} /></span><strong>{item.name}</strong><small>{item.analysis?.recommendedOrientation}</small></button>)}</div></div><div className="camera-controls card"><label><span>Cámara</span><select value={camera} onChange={(event) => setCamera(event.target.value as 'user' | 'environment')}><option value="environment">Trasera</option><option value="user">Frontal</option></select></label><label className="switch-row"><span>Mostrar esqueleto</span><input type="checkbox" checked={skeleton} onChange={(event) => setSkeleton(event.target.checked)} /></label><button className="button lime-button wide" onClick={startCamera}><Video size={18} /> Activar cámara</button>{error && <p className="error-text">{error}</p>}</div></> : <section className="camera-mode"><div className="camera-frame"><video ref={videoRef} playsInline muted /><canvas ref={canvasRef} /><div className="camera-badge"><span className="pulse-dot" /> ANÁLISIS ACTIVO</div><div className="camera-guide"><span>Todo el cuerpo visible</span><span>•</span><span>{exercise?.name}</span></div></div><div className="camera-feedback"><div className="feedback-rep"><span>REP</span><strong>{feedback?.reps ?? 0}</strong></div><div className={feedback?.warnings.length ? 'feedback-message warning' : 'feedback-message'}><strong>{feedback?.warnings[0] ?? feedback?.message ?? 'Buscando tu pose…'}</strong><small>Confianza de detección: {feedback?.confidence ?? 0}%</small></div><button className="button lime-button wide" onClick={stop}><Square size={15} fill="currentColor" /> Finalizar serie</button></div>{error && <p className="error-text">{error}</p>}</section>}</> }
function drawSkeleton(canvas: HTMLCanvasElement, video: HTMLVideoElement, landmarks: Landmark[]) { const ctx = canvas.getContext('2d'); if (!ctx) return; canvas.width = video.videoWidth; canvas.height = video.videoHeight; ctx.clearRect(0, 0, canvas.width, canvas.height); const connections = [['left_shoulder','left_elbow'],['left_elbow','left_wrist'],['right_shoulder','right_elbow'],['right_elbow','right_wrist'],['left_shoulder','right_shoulder'],['left_shoulder','left_hip'],['right_shoulder','right_hip'],['left_hip','right_hip'],['left_hip','left_knee'],['left_knee','left_ankle'],['right_hip','right_knee'],['right_knee','right_ankle']]; const byName = new Map(landmarks.map((point) => [point.name, point])); ctx.strokeStyle = '#c8f169'; ctx.lineWidth = 4; connections.forEach(([a, b]) => { const from = byName.get(a); const to = byName.get(b); if (!from || !to) return; ctx.beginPath(); ctx.moveTo(from.x * canvas.width, from.y * canvas.height); ctx.lineTo(to.x * canvas.width, to.y * canvas.height); ctx.stroke() }); ctx.fillStyle = '#ffffff'; landmarks.forEach((point) => { if ((point.visibility ?? 0) < 0.5) return; ctx.beginPath(); ctx.arc(point.x * canvas.width, point.y * canvas.height, 5, 0, Math.PI * 2); ctx.fill() }) }

function SettingsView({ state, setState }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>> }) { const update = (patch: Partial<AppSettings>) => setState((old) => ({ ...old, settings: { ...old.settings, ...patch } })); const exportData = () => { const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `gymflow-backup-${isoDate()}.json`; link.click(); URL.revokeObjectURL(link.href) }; const importData = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const parsed = JSON.parse(String(reader.result)) as AppState; if (!Array.isArray(parsed.exercises) || !Array.isArray(parsed.sessions) || !parsed.settings) throw new Error('invalid'); setState(parsed) } catch { window.alert('El archivo no tiene un backup válido de GymFlow.') } }; reader.readAsText(file) }; return <><PageTitle eyebrow="PREFERENCIAS" title="Configuración" description="La app se adapta a tu forma de entrenar." /><section className="settings-group"><p className="eyebrow">APARIENCIA</p><div className="setting-row card"><div><strong>Tema</strong><small>Elegí cómo se ve GymFlow</small></div><div className="segmented">{(['dark','light','system'] as const).map((theme) => <button key={theme} className={state.settings.theme === theme ? 'selected' : ''} onClick={() => update({ theme })}>{theme === 'dark' ? <Moon size={15} /> : theme === 'light' ? <Sun size={15} /> : <Activity size={15} />}{theme === 'system' ? 'Sistema' : theme === 'dark' ? 'Oscuro' : 'Claro'}</button>)}</div></div></section><section className="settings-group"><p className="eyebrow">ENTRENAMIENTO</p><div className="setting-row card"><div><strong>Unidad de carga</strong><small>Se usa en pesos y estadísticas</small></div><div className="segmented"><button className={state.settings.unit === 'kg' ? 'selected' : ''} onClick={() => update({ unit: 'kg' })}>kg</button><button className={state.settings.unit === 'lb' ? 'selected' : ''} onClick={() => update({ unit: 'lb' })}>lb</button></div></div>{[['autoRest','Descanso automático','Mostrar el temporizador al completar una serie'],['restSound','Sonido al finalizar descanso','Aviso breve cuando termine'],['vibration','Vibración','Usar vibración si el dispositivo lo permite'],['showSkeleton','Esqueleto en cámara','Dibujar landmarks durante el análisis']].map(([key, title, text]) => <div className="setting-row card" key={key}><div><strong>{title}</strong><small>{text}</small></div><input className="toggle" type="checkbox" checked={Boolean(state.settings[key as keyof AppSettings])} onChange={(event) => update({ [key]: event.target.checked })} /></div>)}</section><section className="settings-group"><p className="eyebrow">TUS DATOS</p><div className="backup-card card"><div className="backup-icon"><Download size={19} /></div><div><strong>Backup local</strong><p className="muted">Guardá o restaurá rutinas, sesiones, PRs y peso corporal en un archivo JSON.</p></div><div className="backup-actions"><button className="button secondary" onClick={exportData}><Download size={16} /> Exportar</button><label className="button ghost"><Upload size={16} /> Importar<input type="file" accept="application/json" onChange={importData} hidden /></label></div></div></section><p className="privacy-note"><CircleHelp size={15} /> Tus datos se guardan en este dispositivo. No hay cuenta ni servidor detrás de tus entrenamientos.</p></> }

export default App
